# --- JIT loader -------------------------------------------------------------------


def _csrc_dir() -> Path:
    packaged = jit_env.FLASHINFER_CSRC_DIR / PACKAGE_DIR
    if packaged.is_dir():
        return packaged
    return Path(__file__).resolve().parents[2] / "csrc" / PACKAGE_DIR


def _source_path(relative: str) -> Path:
    # Registry paths are relative to the package directory.
    path = _csrc_dir() / Path(relative).relative_to(PACKAGE_DIR)
    if not path.is_file():
        raise FileNotFoundError(
            f"generated TRT-LLM MLA Blackwell source is missing: {path}"
        )
    return path


@functools.cache
def gen_cake_trtllm_mla_blackwell_family(name: str) -> JitSpec:
    """JIT spec of one compiled family: its binding plus every device kernel it links."""
    try:
        family = FAMILIES[name]
    except KeyError as exc:
        raise ValueError(
            f"TRT-LLM MLA Blackwell has no generated family {name!r}"
        ) from exc
    arch = family["arch"]
    binding = _source_path(family["binding"])
    sources = [binding]
    flags: list[str] = [*_ARCH_NVCC_FLAGS[arch], *family["compile_flags"]]
    # Compile definitions of a shared source: a binding that serves several
    # families carries this family's values in "binding_flags"; a device source
    # that serves several modules carries its module's values in "source_flags".
    definitions: list[tuple[str | Path, list[str]]] = []
    if family.get("binding_flags"):
        definitions.append((binding, family["binding_flags"]))
    for dependency in family["dependencies"]:
        module = MODULES[dependency]
        device = _source_path(module["device"])
        sources.append(device)
        for flag in module["compile_flags"]:
            if flag not in flags:
                flags.append(flag)
        if module.get("source_flags"):
            definitions.append((device, module["source_flags"]))
    # A per-source list replaces the shared list for that source, so it repeats
    # the shared flags and appends the source's definitions; every other source
    # keeps the shared list.
    flags_by_source = {
        source: [*flags, *source_flags] for source, source_flags in definitions
    }
    csrc_dir = _csrc_dir()
    return gen_jit_spec(
        name=f"cake_trtllm_mla_blackwell_{name}",
        sources=sources,
        extra_cuda_cflags=flags,
        extra_cuda_cflags_by_source=flags_by_source or None,
        # The generated contract owns the fast-math decision.
        use_fast_math=False,
        extra_include_paths=[csrc_dir, csrc_dir.parent],
        extra_ldflags=["-lcuda"],
    )


@functools.cache
def get_cake_trtllm_mla_blackwell_family(name: str):
    return gen_cake_trtllm_mla_blackwell_family(name).build_and_load()


def route_key(domain: str, arch: str, num_sms: Optional[int] = None) -> str:
    if num_sms is None:
        return f"{domain}__{arch}"
    return f"{domain}__{arch}__{num_sms}"


@functools.cache
def family_for(domain: str, arch: str, num_sms: Optional[int] = None) -> str:
    """The family serving ``domain`` on ``arch``.

    A route keyed by the SM count as well (``<domain>__<arch>__<num_sms>``) takes
    precedence on a device of that count: the sm_103a CLC schedule of the 148-SM
    B300 is slower on the 152-SM GB300 than the sm_100a schedule built for sm_103a,
    which also serves the 512x16x1024 geometry there faster than its exact program.
    """
    if num_sms is not None:
        family = ROUTES.get(route_key(domain, arch, num_sms))
        if family is not None:
            return family
    try:
        return ROUTES[route_key(domain, arch)]
    except KeyError as exc:
        raise ValueError(
            f"TRT-LLM MLA Blackwell has no generated family for domain {domain!r} on {arch}"
        ) from exc


def launch_family(domain: str, arch: str, num_sms: int, work_items: int) -> str:
    """The family launching ``work_items`` work items of ``domain`` on ``arch``.

    A generic CLC launch whose work items all start in the first wave of clusters
    (``work_items <= num_sms // 2``) takes the one-wave CLC program where one is
    generated for the device (route ``mla_bf16_clc_one_wave__<arch>__<num_sms>``):
    its idle scheduler warp prefetches the first work item's query rows, KV length
    and page-table entries to L2 at kernel entry.  It is a separate program because
    that code slows the generic program's multi-wave launches.  Every other launch
    takes ``family_for``.
    """
    if domain == DOMAIN_BF16_CLC and work_items <= max(1, num_sms // _CLUSTER_SIZE):
        family = ROUTES.get(route_key(DOMAIN_BF16_CLC_ONE_WAVE, arch, num_sms))
        if family is not None:
            return family
    return family_for(domain, arch, num_sms)


def _uses_work_order(num_sms: int, total_q: int) -> bool:
    """Whether a generic CLC launch of ``total_q`` rows takes the device work order:
    more rows than one wave of clusters and at most ``_MAX_ORDERED_ROWS`` rows."""
    return max(1, num_sms // _CLUSTER_SIZE) < total_q <= _MAX_ORDERED_ROWS


def launch_families(
    domain: str, arch: str, num_sms: int, total_q: int
) -> tuple[str, ...]:
    """The families a launch of ``total_q`` rows of ``domain`` runs, in launch order.

    The attention family (``launch_family``), preceded by the longest-first order
    family when the launched binding is the generic CLC binding and the launch
    takes the device work order.
    """
    family = launch_family(domain, arch, num_sms, total_q)
    if FAMILIES[family]["binding"] == _CLC_BINDING and _uses_work_order(
        num_sms, total_q
    ):
        return (family_for(DOMAIN_BF16_CLC_ORDER, arch, num_sms), family)
    return (family,)


# --- Device facts (cached once per device index) ------------------------------------


@functools.cache
def _device_facts(index: int) -> tuple[str, int]:
    capability = tuple(torch.cuda.get_device_capability(index))
    arch = _ARCH_BY_CAPABILITY.get(capability)
    if arch is None:
        raise RuntimeError(
            "TRT-LLM MLA Blackwell requires compute capability 10.0 or 10.3, "
            f"got {capability[0]}.{capability[1]}"
        )
    return arch, int(torch.cuda.get_device_properties(index).multi_processor_count)


